-- 6 konten Berita & Informasi tentang wisata dan destinasi Batam (status draft, tanpa gambar).
-- Isi teks ASCII saja (aman dari masalah encoding PowerShell). Aman dijalankan ulang: judul EN yang sama dilewati.
-- Jalankan: Get-Content database\seed_news.sql -Raw | mysql -u root -h 127.0.0.1 -P 3307 --default-character-set=utf8mb4
USE `tour_travel`;
SET NAMES utf8mb4;

INSERT INTO `c_news` (`title_en`,`title_id`,`title_ms`,`body_en`,`body_id`,`body_ms`,`image_path`,`publish_date`,`status`,`created_at`,`updated_at`)
SELECT * FROM (
  SELECT 'Barelang Bridge: Batam Iconic Road Trip' AS title_en,
         'Jembatan Barelang: Ikon Wisata Road Trip Batam' AS title_id,
         'Jambatan Barelang: Ikon Perjalanan Darat Batam' AS title_ms,
         'Barelang Bridge is a chain of six bridges, built in 1997, that links Batam with Rempang and Galang islands. The name Barelang comes from the three islands it connects: BAtam, REmpang and GAlang.\n\nThe bridges lie roughly 35 km from Batam city, so the drive itself is part of the fun, with sea views and island scenery along the way. Each span looks different, and the cable-stayed ones make the best photo stops.\n\nTip: travel in the morning or late afternoon to avoid the midday heat, and bring water. A rental car or van with a driver lets you stop wherever you like.' AS body_en,
         'Jembatan Barelang adalah rangkaian enam jembatan yang dibangun pada 1997 untuk menghubungkan Pulau Batam dengan Pulau Rempang dan Galang. Nama Barelang berasal dari tiga pulau yang dihubungkannya: BAtam, REmpang, dan GAlang.\n\nJembatan ini berjarak sekitar 35 km dari pusat Kota Batam, sehingga perjalanannya sendiri sudah menjadi bagian dari wisata, dengan pemandangan laut dan pulau di sepanjang jalan. Setiap bentang jembatan punya bentuk berbeda, dan jembatan kabel menjadi spot foto favorit.\n\nTips: berangkat pagi atau sore hari agar tidak terlalu panas, dan bawa air minum. Dengan mobil atau van sewaan beserta sopir, Anda bebas berhenti di titik mana pun.' AS body_id,
         'Jambatan Barelang ialah rangkaian enam jambatan yang dibina pada 1997 untuk menghubungkan Pulau Batam dengan Pulau Rempang dan Galang. Nama Barelang datang daripada tiga pulau yang dihubungkannya: BAtam, REmpang dan GAlang.\n\nJambatan ini terletak kira-kira 35 km dari pusat bandar Batam, jadi perjalanannya sendiri sudah menjadi sebahagian daripada pengalaman, dengan pemandangan laut dan pulau sepanjang jalan. Setiap rentang jambatan berbeza bentuknya, dan jambatan kabel menjadi tempat bergambar yang digemari.\n\nPetua: bertolak pada waktu pagi atau lewat petang supaya tidak terlalu panas, dan bawa air minuman. Dengan kereta atau van sewa berserta pemandu, anda boleh berhenti di mana-mana sahaja.' AS body_ms,
         NULL AS image_path, DATE_SUB(NOW(), INTERVAL 0 DAY) AS publish_date, 'draft' AS status, NOW() AS created_at, NOW() AS updated_at
  UNION ALL
  SELECT 'Galang and Rempang: History and Coastal Village Life',
         'Galang dan Rempang: Sejarah dan Kehidupan Kampung Pesisir',
         'Galang dan Rempang: Sejarah dan Kehidupan Kampung Pesisir',
         'South of Batam, Galang and Rempang islands offer a quieter side of the Riau Islands. Galang is known for its former Vietnamese refugee camp, a historic site that many visitors combine with a trip across the Barelang bridges.\n\nRempang is a rural island dotted with coastal villages built on stilts over the water, a good place to see everyday island life and try local dishes.\n\nBoth islands are easy to reach by road from Batam. Plan a full day, and ask us about a driver who knows the route.',
         'Di selatan Batam, Pulau Galang dan Rempang menawarkan sisi Kepulauan Riau yang lebih tenang. Galang dikenal karena bekas kamp pengungsi Vietnam, situs bersejarah yang sering dikunjungi sekaligus dalam perjalanan melintasi jembatan Barelang.\n\nRempang adalah pulau pedesaan dengan kampung-kampung pesisir berumah panggung di atas air, tempat yang pas untuk melihat keseharian warga pulau dan mencicipi hidangan lokal.\n\nKedua pulau mudah dijangkau lewat jalan darat dari Batam. Sediakan waktu satu hari penuh, dan tanyakan kepada kami soal sopir yang mengenal rutenya.',
         'Di selatan Batam, Pulau Galang dan Rempang menawarkan sisi Kepulauan Riau yang lebih tenang. Galang terkenal dengan bekas kem pelarian Vietnam, tapak bersejarah yang sering dikunjungi sekali gus dalam perjalanan merentasi jambatan Barelang.\n\nRempang ialah pulau luar bandar dengan kampung-kampung pesisir berumah panggung di atas air, tempat yang sesuai untuk melihat kehidupan harian penduduk pulau dan mencuba hidangan tempatan.\n\nKedua-dua pulau mudah dihubungi melalui jalan darat dari Batam. Peruntukkan masa sehari penuh, dan tanyalah kami tentang pemandu yang mengenali laluannya.',
         NULL, DATE_SUB(NOW(), INTERVAL 1 DAY), 'draft', NOW(), NOW()
  UNION ALL
  SELECT 'Maha Vihara Duta Maitreya: A Peaceful Stop in Batam',
         'Maha Vihara Duta Maitreya: Singgah Tenang di Batam',
         'Maha Vihara Duta Maitreya: Persinggahan Tenang di Batam',
         'Maha Vihara Duta Maitreya is one of the largest Buddhist temples in Southeast Asia. Its grounds cover about 4.5 hectares with five buildings, and the main hall, Graha Maitreya, can hold around 2,000 people.\n\nVisitors come for the calm gardens, the koi pond and the golden Maitreya Buddha statue, and it is a favourite stop on city tours.\n\nPlease dress modestly and respect the worshippers. It is a short drive from the city centre, so it fits easily into a half-day tour.',
         'Maha Vihara Duta Maitreya adalah salah satu vihara terbesar di Asia Tenggara. Kompleksnya seluas sekitar 4,5 hektare dengan lima bangunan, dan aula utamanya, Graha Maitreya, dapat menampung sekitar 2.000 orang.\n\nPengunjung datang untuk menikmati taman yang asri, kolam ikan koi, dan patung Buddha Maitreya berlapis emas. Tempat ini menjadi persinggahan favorit dalam city tour.\n\nMohon berpakaian sopan dan hormati umat yang beribadah. Lokasinya hanya sejauh perjalanan singkat dari pusat kota, sehingga cocok untuk tur setengah hari.',
         'Maha Vihara Duta Maitreya ialah salah sebuah vihara Buddha terbesar di Asia Tenggara. Kawasannya seluas kira-kira 4.5 hektar dengan lima bangunan, dan dewan utamanya, Graha Maitreya, boleh memuatkan kira-kira 2,000 orang.\n\nPengunjung datang untuk menikmati taman yang tenang, kolam ikan koi dan patung Buddha Maitreya bersalut emas. Tempat ini menjadi persinggahan kegemaran dalam lawatan bandar.\n\nSila berpakaian sopan dan hormati para penyembah. Lokasinya hanya perjalanan singkat dari pusat bandar, sesuai untuk lawatan separuh hari.',
         NULL, DATE_SUB(NOW(), INTERVAL 2 DAY), 'draft', NOW(), NOW()
  UNION ALL
  SELECT 'Nongsa Beach and Pulau Abang: Sea and Snorkelling',
         'Pantai Nongsa dan Pulau Abang: Wisata Laut dan Snorkeling',
         'Pantai Nongsa dan Pulau Abang: Pelancongan Laut dan Snorkeling',
         'Nongsa, in the north-east of Batam, is a popular beach area. It is said to be named after Nong Isa, a ruler of the region in the 18th century.\n\nFor snorkelling and diving, Pulau Abang is one of the island destinations around Batam, reached by boat.\n\nPlan the transfer in advance: we can take you to the beach or the pier, and pick you up again when your trip ends.',
         'Nongsa di timur laut Batam adalah kawasan pantai yang populer. Namanya dikatakan berasal dari Nong Isa, penguasa wilayah ini pada abad ke-18.\n\nUntuk snorkeling dan menyelam, Pulau Abang menjadi salah satu destinasi pulau di sekitar Batam yang dijangkau dengan perahu.\n\nRencanakan transportasi sejak awal: kami dapat mengantar Anda ke pantai atau dermaga, dan menjemput kembali saat perjalanan selesai.',
         'Nongsa di timur laut Batam ialah kawasan pantai yang popular. Namanya dikatakan berasal daripada Nong Isa, pemerintah wilayah ini pada abad ke-18.\n\nUntuk snorkeling dan menyelam, Pulau Abang ialah salah satu destinasi pulau di sekitar Batam yang dihubungi dengan bot.\n\nRancang pengangkutan lebih awal: kami boleh menghantar anda ke pantai atau jeti, dan mengambil anda semula apabila perjalanan tamat.',
         NULL, DATE_SUB(NOW(), INTERVAL 3 DAY), 'draft', NOW(), NOW()
  UNION ALL
  SELECT 'Foreign Visits to Batam Keep Rising',
         'Kunjungan Wisatawan Mancanegara ke Batam Terus Naik',
         'Kunjungan Pelancong Asing ke Batam Terus Meningkat',
         'Batam continues to attract more international visitors. Statistics Indonesia (BPS) data, as reported in the media, shows 861,712 foreign tourist visits to Batam from January to July 2025, up 21.7% from the same period in 2024.\n\nFor the whole of 2024, foreign visits exceeded 1.16 million, compared with about 1.04 million the year before. In November 2024, Singapore alone made up about 52% of foreign visits, followed by Malaysia.\n\nMore visitors means busier weekends and holidays. If you plan a trip, we recommend booking your vehicle early so your preferred car, van or bus is available.',
         'Batam terus menarik semakin banyak wisatawan mancanegara. Data Badan Pusat Statistik (BPS) yang diberitakan media mencatat 861.712 kunjungan wisatawan mancanegara ke Batam pada Januari-Juli 2025, naik 21,7% dibanding periode yang sama tahun 2024.\n\nSepanjang 2024, kunjungan wisatawan mancanegara melampaui 1,16 juta, dibanding sekitar 1,04 juta pada tahun sebelumnya. Pada November 2024, Singapura saja menyumbang sekitar 52% kunjungan, disusul Malaysia.\n\nPengunjung yang lebih banyak berarti akhir pekan dan musim libur lebih ramai. Jika Anda berencana datang, kami sarankan memesan kendaraan lebih awal agar mobil, van, atau bus pilihan Anda tersedia.',
         'Batam terus menarik lebih ramai pelancong antarabangsa. Data Badan Pusat Statistik (BPS) yang dilaporkan media mencatatkan 861,712 kunjungan pelancong asing ke Batam pada Januari hingga Julai 2025, meningkat 21.7% berbanding tempoh yang sama pada 2024.\n\nSepanjang 2024, kunjungan pelancong asing melebihi 1.16 juta, berbanding kira-kira 1.04 juta pada tahun sebelumnya. Pada November 2024, Singapura sahaja menyumbang kira-kira 52% kunjungan, diikuti Malaysia.\n\nPengunjung yang lebih ramai bermakna hujung minggu dan musim cuti lebih sibuk. Jika anda merancang perjalanan, kami syorkan menempah kenderaan lebih awal supaya kereta, van atau bas pilihan anda tersedia.',
         NULL, DATE_SUB(NOW(), INTERVAL 4 DAY), 'draft', NOW(), NOW()
  UNION ALL
  SELECT 'From Singapore to Batam: Ferry Terminals and Pickup Tips',
         'Dari Singapura ke Batam: Pelabuhan Feri dan Tips Penjemputan',
         'Dari Singapura ke Batam: Terminal Feri dan Petua Pengambilan',
         'Batam is about 30 minutes by ferry from Singapore, which makes it an easy weekend trip. Ferries run from terminals such as HarbourFront and Tanah Merah in Singapore to Batam Center and Sekupang in Batam.\n\nBring your passport, and check the ferry schedule before you travel. Arrange your pickup in advance: tell us your arrival terminal and time, and a driver will be waiting.\n\nFrom the port we can take you straight to your hotel, to Barelang Bridge, or on a full city tour.',
         'Batam hanya sekitar 30 menit dengan feri dari Singapura, sehingga mudah untuk liburan akhir pekan. Feri berangkat dari terminal seperti HarbourFront dan Tanah Merah di Singapura menuju Batam Center dan Sekupang di Batam.\n\nBawa paspor Anda dan cek jadwal feri sebelum berangkat. Atur penjemputan sejak awal: beri tahu kami terminal dan jam kedatangan, dan sopir akan menunggu Anda.\n\nDari pelabuhan, kami dapat mengantar Anda langsung ke hotel, ke Jembatan Barelang, atau untuk city tour sehari penuh.',
         'Batam hanya kira-kira 30 minit dengan feri dari Singapura, jadi mudah untuk percutian hujung minggu. Feri bertolak dari terminal seperti HarbourFront dan Tanah Merah di Singapura menuju Batam Center dan Sekupang di Batam.\n\nBawa pasport anda dan semak jadual feri sebelum bertolak. Atur pengambilan lebih awal: beritahu kami terminal dan waktu ketibaan, dan pemandu akan menunggu anda.\n\nDari pelabuhan, kami boleh menghantar anda terus ke hotel, ke Jambatan Barelang, atau untuk lawatan bandar sehari penuh.',
         NULL, DATE_SUB(NOW(), INTERVAL 5 DAY), 'draft', NOW(), NOW()
) AS new_news
WHERE NOT EXISTS (
  SELECT 1 FROM `c_news` n WHERE n.`title_en` = new_news.`title_en` COLLATE utf8mb4_unicode_ci AND n.`status` <> 'deleted'
);